import sys

def main():
    a, b = sys.stdin.read().split()[:2]
    if len(b) > len(a):
        a, b = b, a
    prev = [0] * (len(b) + 1)
    for ch in a:
        cur = [0]
        for j, c in enumerate(b):
            if ch == c:
                cur.append(prev[j] + 1)
            else:
                cur.append(max(prev[j + 1], cur[j]))
        prev = cur
    print(prev[-1])

main()

